module.exports="\n.audience [role=tablist]{display:flex;flex-wrap:wrap;gap:6px}\n#simulation-panel{max-width:var(--doc-layout-width);margin:auto;padding:36px var(--doc-layout-gutter) 64px}\n#simulation-panel h1{font-size:var(--doc-type-title);line-height:1.3;letter-spacing:-.04em;margin:12px 0}\n#simulation-panel .sim-intro{color:var(--doc-color-muted);margin:0 0 24px}\n#simulation-panel .sim-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:24px 0}\n#simulation-panel .sim-base-fields{grid-template-columns:repeat(5,minmax(0,1fr))}\n#simulation-panel label{display:flex;flex-direction:column;gap:8px;font-size:15px}\n#simulation-panel input{width:100%;min-width:0;padding:10px 12px;border:1px solid var(--doc-color-line);border-radius:6px;background:var(--doc-color-surface);color:var(--doc-color-ink);font:inherit;font-variant-numeric:tabular-nums}\n#simulation-panel input:focus-visible,#simulation-panel button:focus-visible{outline:2px solid var(--doc-color-teal);outline-offset:3px}\n#simulation-panel button{font:inherit;font-size:15px;cursor:pointer;padding:10px 16px;border:1px solid var(--doc-color-line);border-radius:6px;background:var(--doc-color-surface);color:var(--doc-color-ink)}\n#simulation-panel button.sim-primary{background:var(--doc-color-ink);color:var(--doc-color-surface)}\n#simulation-panel .sim-toolbar{display:flex;align-items:end;flex-wrap:wrap;gap:12px;margin:20px 0}\n#simulation-panel .sim-toolbar label{flex:1 1 160px;max-width:230px}\n#simulation-panel .sim-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:24px 0}\n#simulation-panel .sim-metric{padding:20px 24px;background:var(--doc-color-wash);border-top:3px solid var(--doc-color-teal)}\n#simulation-panel .sim-metric span{display:block;font-size:15px;color:var(--doc-color-muted)}\n#simulation-panel .sim-metric strong{display:block;font-size:30px;letter-spacing:-.025em;font-variant-numeric:tabular-nums}\n#simulation-panel .sim-unit{font-size:14px;color:var(--doc-color-muted)}\n#simulation-panel .sim-table{min-width:1060px;font-size:15px;background:var(--doc-color-surface);font-variant-numeric:tabular-nums}\n#simulation-panel .sim-table th,#simulation-panel .sim-table td{padding:12px;text-align:right;white-space:nowrap;vertical-align:middle;width:auto;font-weight:400}\n#simulation-panel .sim-table th:first-child,#simulation-panel .sim-table td:first-child{text-align:left;font-weight:600}\n#simulation-panel .sim-table thead th,#simulation-panel .sim-table tfoot th,#simulation-panel .sim-table tfoot td{background:var(--doc-color-wash);font-weight:600}\n#simulation-panel .sim-table input{width:115px;text-align:right;padding:8px}\n#simulation-panel .sim-table .sim-result{font-weight:700}\n#simulation-panel .sim-region{min-width:580px;margin:24px 0}\n#simulation-panel .sim-details{margin-top:28px;border-top:1px solid var(--doc-color-line);padding-top:20px}\n#simulation-panel summary{cursor:pointer;font-weight:600}\n#simulation-panel .sim-note{font-size:14px;color:var(--doc-color-muted);line-height:1.8;margin:12px 0}\n#simulation-panel .sim-error{color:var(--doc-color-ink);border-left:4px solid var(--doc-color-coral);background:var(--doc-color-wash);padding:12px 16px}\n#simulation-panel .sim-months{margin-top:28px}\n#simulation-panel [data-negative=true]{color:var(--doc-color-ink);text-decoration:underline;text-decoration-color:var(--doc-color-coral);text-underline-offset:5px}\n@media(max-width:760px){#simulation-panel{padding:24px var(--doc-layout-mobileGutter) 48px}#simulation-panel h1{font-size:var(--doc-type-mobileTitle)}#simulation-panel .sim-fields{grid-template-columns:repeat(2,minmax(0,1fr))}#simulation-panel .sim-metrics{grid-template-columns:1fr}#simulation-panel .sim-metric strong{font-size:28px}}\n@media print{body[data-audience=simulation] #investor-panel{display:none!important}body[data-audience=simulation] #simulation-panel{display:block!important;max-width:none;padding:0}#simulation-panel .sim-toolbar,#simulation-panel .sim-details{display:none}#simulation-panel .sim-table{min-width:0;font-size:9pt}#simulation-panel .sim-table th,#simulation-panel .sim-table td{padding:5px}#simulation-panel .sim-table input{width:60px;border:0;padding:0;font-size:9pt}#simulation-panel .table-wrap{overflow:visible}}\n";
